<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(403);exit("Somente CLI.\n");}
$root=dirname(__DIR__);require_once $root.'/config/nexa_env.php';require $root.'/config/pdo.php';require_once $root.'/config/fiscal_module.php';
$opts=getopt('', ['type:','file:','uf::']);$type=strtolower(trim((string)($opts['type']??'')));$file=(string)($opts['file']??'');$uf=strtoupper(trim((string)($opts['uf']??'')));
if($type===''||$file===''||!is_file($file)){fwrite(STDERR,"Uso: php workers/import_global_fiscal_catalog_v26.php --type=TIPO --file=/caminho/arquivo [--uf=MG]\nTipos: ncm, cest, ibpt, ibscbs, municipios, ufs, cbs-rates, ibs-uf-rates, ibs-mun-rates\n");exit(2);}fiscal_ensure_schema($pdo);fiscal_ensure_aux_schema($pdo);
function norm_header(string $s):string{$s=fiscal_clean_utf8($s);return strtolower(preg_replace('/[^a-z0-9]+/i','',iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$s)?:$s));}
function import_rates(PDO $pdo,string $type,string $file):array{
 $fh=fopen($file,'rb');if(!$fh)throw new RuntimeException('Não foi possível abrir o arquivo.');$first=fgets($fh);if($first===false)throw new RuntimeException('Arquivo vazio.');$d=substr_count($first,';')>=substr_count($first,',')?';':',';$h=fiscal_clean_csv_row(str_getcsv(trim($first),$d));$map=[];foreach($h as $i=>$v)$map[norm_header($v)]=$i;$idx=fn(array $names)=>array_reduce($names,fn($c,$n)=>$c??($map[$n]??null),null);
 $iRate=$idx(['rate','aliquota','percentual']);$iIni=$idx(['validitystart','vigenciainicio','inicio']);$iFim=$idx(['validityend','vigenciafim','fim']);if($iRate===null)throw new RuntimeException('Informe a coluna rate/alíquota.');$total=0;$imported=0;
 if($type==='cbs-rates'){$iCode=$idx(['code','codigo']);$st=$pdo->prepare("INSERT INTO fiscal_cbs_rates (company_id,code,validity_start,validity_end,rate,is_active,notes,updated_at) VALUES (0,?,?,?,?,1,'Importação global v2.6',NOW()) ON DUPLICATE KEY UPDATE rate=VALUES(rate),is_active=1,updated_at=NOW()");}
 elseif($type==='ibs-uf-rates'){$iUf=$idx(['uf','sigla']);if($iUf===null)throw new RuntimeException('Informe a coluna UF.');$st=$pdo->prepare("INSERT INTO fiscal_ibs_uf_rates (company_id,uf,validity_start,validity_end,rate,is_active,notes,updated_at) VALUES (0,?,?,?,?,1,'Importação global v2.6',NOW()) ON DUPLICATE KEY UPDATE rate=VALUES(rate),is_active=1,updated_at=NOW()");}
 else{$iIbge=$idx(['ibgecode','ibge','codigoibge']);$iCity=$idx(['cityname','municipio','cidade','nome']);$iUf=$idx(['uf','sigla']);if($iIbge===null)throw new RuntimeException('Informe a coluna IBGE.');$st=$pdo->prepare("INSERT INTO fiscal_ibs_mun_rates (company_id,ibge_code,city_name,uf,validity_start,validity_end,rate,is_active,notes,updated_at) VALUES (0,?,?,?,?,?,?,1,'Importação global v2.6',NOW()) ON DUPLICATE KEY UPDATE city_name=VALUES(city_name),uf=VALUES(uf),rate=VALUES(rate),is_active=1,updated_at=NOW()");}
 while(($r=fgetcsv($fh,0,$d))!==false){$total++;$rate=fiscal_decimal($r[$iRate]??0);$ini=$iIni!==null?fiscal_date_from_br($r[$iIni]??''):null;$fim=$iFim!==null?fiscal_date_from_br($r[$iFim]??''):null;if($type==='cbs-rates'){$st->execute([trim((string)($r[$iCode]??'PADRAO'))?:'PADRAO',$ini,$fim,$rate]);}elseif($type==='ibs-uf-rates'){$u=strtoupper(substr(preg_replace('/[^A-Za-z]/','',(string)($r[$iUf]??'')),0,2));if($u==='')continue;$st->execute([$u,$ini,$fim,$rate]);}else{$ibge=substr(preg_replace('/\D+/','',(string)($r[$iIbge]??''))?:'',0,7);if($ibge==='')continue;$city=$iCity!==null?trim((string)($r[$iCity]??'')):'';$u=$iUf!==null?strtoupper(substr(preg_replace('/[^A-Za-z]/','',(string)($r[$iUf]??'')),0,2)):null;$st->execute([$ibge,$city,$u,$ini,$fim,$rate]);}$imported++;}fclose($fh);return ['ok'=>true,'message'=>"{$type}: {$imported} registro(s).",'total'=>$total,'imported'=>$imported];
}
try{switch($type){case'ncm':$res=fiscal_import_ncm_csv_file($pdo,$file,basename($file));break;case'cest':$res=fiscal_import_cests_csv_file($pdo,0,$file,basename($file));break;case'ibpt':$res=fiscal_import_ibpt_file($pdo,0,$file,basename($file),$uf);break;case'ibscbs':$res=fiscal_import_ibs_cbs_json_file($pdo,$file,basename($file),0);break;case'municipios':$res=fiscal_import_cities_json_file($pdo,$file,basename($file),0);break;case'ufs':$res=fiscal_import_states_json_file($pdo,$file,basename($file),0);break;case'cbs-rates':case'ibs-uf-rates':case'ibs-mun-rates':$res=import_rates($pdo,$type,$file);break;default:throw new RuntimeException('Tipo inválido.');}
if(!empty($res['ok'])&&!in_array($type,['ncm','ibpt'],true)){$hash=@hash_file('sha256',$file)?:null;$st=$pdo->prepare("INSERT INTO fiscal_catalog_imports (catalog_type,uf,filename,source,source_hash,rows_total,rows_imported,status,notes) VALUES (?,?,?,?,?,?,?,'CONCLUIDO','Importação global v2.6')");$st->execute([strtoupper($type),$uf!==''?$uf:null,basename($file),'ADMIN_CLI',$hash,(int)($res['total']??0),(int)($res['imported']??0)]);}
echo (!empty($res['ok'])?'[OK] ':'[ERRO] ').($res['message']??'')."\n";exit(!empty($res['ok'])?0:1);}catch(Throwable $e){fwrite(STDERR,'[ERRO] '.$e->getMessage()."\n");exit(1);}
